// <diletta-web-stepper-node> — a INSTÂNCIA WEB de `design-system-web-stepper-node`.
//
// Não é o `DilettaStepper`, que é a régua horizontal do onboarding no celular:
// aqui cada degrau CARREGA motivo e ação, e é isso que o torna outra peça.
const ESTADO = ['concluido', 'bloqueado', 'pendente'];
const TINTA = { concluido: 'primary', bloqueado: 'warning', pendente: 'textMuted' };
const GLIFO = {
  concluido: '<path d="M4 8.5l3 3 5-6" stroke="currentColor" stroke-width="1.6" fill="none" stroke-linecap="round" stroke-linejoin="round"/>',
  bloqueado: '<rect x="4" y="7" width="8" height="6" rx="1.5" stroke="currentColor" stroke-width="1.4" fill="none"/><path d="M6 7V5.5a2 2 0 014 0V7" stroke="currentColor" stroke-width="1.4" fill="none"/>',
  pendente: '<circle cx="8" cy="8" r="2.2" stroke="currentColor" stroke-width="1.4" fill="none"/><path d="M8 3v1.5M8 11.5V13M3 8h1.5M11.5 8H13" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/>',
};

class DilettaWebStepperNode extends HTMLElement {
  static observedAttributes = ['estado', 'titulo', 'descricao', 'motivo', 'ultimo'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get estado() {
    const v = this.getAttribute('estado');
    return ESTADO.includes(v) ? v : 'pendente';
  }

  render() {
    const e = this.estado;
    const tinta = TINTA[e];
    const motivo = this.getAttribute('motivo') || '';
    const temAcao = !!this.querySelector('[slot="acao"]');

    // O GLIFO é DERIVADO do estado e não passado por quem chama: medalhão que
    // aceita glifo livre deixa um degrau concluído mostrar cadeado.
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        .degrau { display: grid; grid-template-columns: 32px 1fr; gap: 12px; }
        .medalhao {
          width: 32px; height: 32px; border-radius: 999px;
          display: flex; align-items: center; justify-content: center;
          background: ${e === 'concluido' ? 'var(--cps-primary)' : 'transparent'};
          color: var(--cps-${e === 'concluido' ? 'onPrimary' : tinta});
          border-width: ${e === 'concluido' ? 0 : 1}px; border-style: solid;
          border-color: var(--cps-${tinta});
        }
        .medalhao svg { width: 16px; height: 16px; }
        /* O FIO é da ESTEIRA, não do degrau: degrau que desenha fio pinta fio
           depois do último. Aqui ele só existe quando o degrau NÃO é o último. */
        .fio { width: 1px; margin: 4px auto 0; flex: 1;
               background: var(--cps-border); min-height: 12px; }
        .coluna { display: flex; flex-direction: column; align-items: center; }
        .titulo { color: var(--cps-fg); }
        .descricao { color: var(--cps-textSecondary); font-size: var(--cps-type-caption-size, 12px); }
        .motivo { color: var(--cps-warning); font-size: var(--cps-type-caption-size, 12px); }
        .corpo { display: flex; flex-direction: column; gap: 4px; padding-bottom: ${temAcao || motivo ? 16 : 8}px; }
      </style>
      <div class="degrau" part="degrau">
        <div class="coluna">
          <span class="medalhao" aria-hidden="true">
            <svg viewBox="0 0 16 16" focusable="false">${GLIFO[e]}</svg></span>
          ${this.hasAttribute('ultimo') ? '' : '<span class="fio"></span>'}
        </div>
        <div class="corpo">
          <span class="titulo">${this.getAttribute('titulo') || ''}</span>
          ${this.getAttribute('descricao') ? `<span class="descricao">${this.getAttribute('descricao')}</span>` : ''}
          ${motivo ? `<span class="motivo">${motivo}</span>` : ''}
          <slot name="acao"></slot>
        </div>
      </div>`;
  }
}

customElements.define('diletta-web-stepper-node', DilettaWebStepperNode);
export { DilettaWebStepperNode, TINTA };
